card.querySelector('[data-act="save"]').addEventListener('click', async () => {
  const newUrl = normalizeUrl(card.querySelector('.edit-url').value) || b.url;
  const refetch = card.querySelector('.edit-refetch').checked;
  b.url = newUrl;
  if (refetch) {
    b.editing = false; b.pending = true; render();
    const details = await fakeFetch(newUrl);
    Object.assign(b, details, { pending: false, edited: true });
    render();
    return;
  }
  b.title = card.querySelector('.edit-title').value.trim() || b.title;
  b.description = card.querySelector('.edit-desc').value.trim();
  // keep favicon/host in sync with the (possibly) changed link
  try { b.host = new URL(newUrl).hostname.replace(/^www\./,''); b.favicon = "https://www.google.com/s2/favicons?domain=" + b.host + "&sz=64"; } catch(e) {}
  b.edited = true;
  b.editing = false;
  render();
});

