// Fetch details for an entry, handling the failure case by keeping the
// bookmark saved with the link as a fallback title.
async function resolveDetails(entry) {
  entry.pending = true; entry.error = false; render();
  const details = await fakeFetch(entry.url);
  if (details.error) {
    let host = details.host || entry.url;
    Object.assign(entry, {
      pending: false, error: true, host: host,
      title: entry.title || entry.url,
      description: entry.description || "",
      favicon: "https://www.google.com/s2/favicons?domain=" + host + "&sz=64",
      image: entry.image || ""
    });
  } else {
    Object.assign(entry, details, { pending: false, error: false });
  }
}

