.editor .checkline { text-transform: none; letter-spacing: 0; font-size: 13px; color: var(--ink); display: flex; align-items: center; gap: 6px; }
.editor .checkline input { width: auto; }
.chip-input { display: flex; flex-wrap: wrap; gap: 6px; border: 1px solid var(--line); border-radius: 7px; padding: 6px; }
.chip-input input { border: none; outline: none; flex: 1; min-width: 120px; font-size: 14px; padding: 3px; }
.editor .row { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
.editor .row button { border-radius: 7px; padding: 7px 14px; font-size: 13px; font-weight: 600; cursor: pointer; border: 1px solid var(--line); }
.editor .save { background: var(--accent); color: #fff; border-color: var(--accent); }
.editor .cancel { background: #fff; color: var(--ink); }

/* Loading skeleton */
.card.pending .body { display: flex; flex-direction: column; justify-content: center; }
.skeleton { background: #eef1f5; border-radius: 6px; height: 12px; }
.skeleton.t { height: 16px; width: 55%; margin-bottom: 10px; }
.skeleton.d { width: 90%; margin-bottom: 6px; }
.skeleton.d2 { width: 70%; }
.fetching { color: var(--muted); font-size: 12px; }
.spin {
  display: inline-block; width: 13px; height: 13px; border: 2px solid var(--line);
  border-top-color: var(--accent); border-radius: 50%; animation: sp .7s linear infinite;
  vertical-align: -2px; margin-right: 6px;
}
@keyframes sp { to { transform: rotate(360deg); } }

/* Empty states */
.empty {
  text-align: center; color: var(--muted); padding: 60px 20px;
  border: 1px dashed var(--line); border-radius: 12px; margin-top: 16px;
}
.empty[hidden] { display: none; }
.empty strong { color: var(--ink); }

toolUseResult.content:
:root {
  --bg: #f5f6f8;
  --card: #ffffff;
  --ink: #1d2430;
  --muted: #6b7580;
  --line: #e4e7eb;
  --accent: #2f6fed;
  --accent-ink: #ffffff;
  --warn-bg: #fdeeec;
  --warn-line: #f6d5cf;
  --warn-ink: #a23b2d;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--ink);
}

.wrap { max-width: 760px; margin: 0 auto; padding: 0 24px; }

.app-header {
  background: var(--card);
  border-bottom: 1px solid var(--line);
  padding: 18px 0;
}
.app-header h1 { margin: 0; font-size: 20px; }
.app-header p { margin: 4px 0 0; color: var(--muted); font-size: 13px; }

main.wrap { padding-top: 24px; padding-bottom: 48px; }

/* Saver */
.saver {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 16px;
  display: flex;
  gap: 10px;
}
.saver input {
  flex: 1;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 11px 12px;
  font-size: 15px;
  outline: none;
}
.saver input:focus { border-color: var(--accent); }
.saver button {
  border: none;
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 8px;
  padding: 0 20px;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
}
.saver button:disabled { opacity: .55; cursor: default; }

/* Notice banner */
.notice {
  margin-top: 12px;
  background: #eef3ff;
  border: 1px solid #d7e2fb;
  color: #2554b0;
  border-radius: 9px;
  padding: 10px 12px;
  font-size: 13.5px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
}
.notice[hidden] { display: none; }
.notice.warn { background: var(--warn-bg); border-color: var(--warn-line); color: var(--warn-ink); }
.notice button {
  background: none; border: none; color: inherit; font-weight: 600;
  cursor: pointer; font-size: 13px; text-decoration: underline;
}

/* View tabs */
.viewbar { margin-top: 18px; display: flex; gap: 6px; border-bottom: 1px solid var(--line); }
.viewtab {
  background: none; border: none; border-bottom: 2px solid transparent;
  padding: 10px 14px; font-size: 14px; font-weight: 600; color: var(--muted);
  cursor: pointer; margin-bottom: -1px;
}
.viewtab.on { color: var(--accent); border-bottom-color: var(--accent); }
.viewtab .count { font-weight: 500; color: var(--muted); font-size: 12px; margin-left: 5px; }

/* Finder */
.finder { margin-top: 16px; }
.finder #searchInput {
  width: 100%; border: 1px solid var(--line); border-radius: 10px;
  padding: 12px 14px; font-size: 15px; outline: none; background: #fff;
}
.finder #searchInput:focus { border-color: var(--accent); }
.searchhint { margin: 7px 0 0; color: var(--muted); font-size: 12px; }
.searchhint code { background: #eef1f5; border-radius: 4px; padding: 1px 5px; font-size: 11.5px; }

.filterbar { margin-top: 12px; display: flex; flex-wrap: wrap; gap: 7px; align-items: center; }
.filterbar .flabel { font-size: 12px; color: var(--muted); margin-right: 2px; }
.filter-chip {
  background: #f3f4f6; color: #444; border: 1px solid var(--line);
  border-radius: 999px; padding: 4px 11px; font-size: 12.5px; cursor: pointer;
}
.filter-chip.on { background: var(--accent); color: #fff; border-color: var(--accent); }
.clearf { font-size: 12px; color: var(--accent); cursor: pointer; background: none; border: none; font-weight: 600; }

.resultmeta { margin: 16px 0 0; color: var(--muted); font-size: 12.5px; min-height: 16px; }

/* List + cards */
.list { margin-top: 8px; display: flex; flex-direction: column; gap: 14px; }

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
  display: flex;
  animation: rise .25s ease;
}
@keyframes rise { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
.card.flash { animation: flash 1.4s ease; }
@keyframes flash {
  0%, 100% { box-shadow: 0 0 0 0 rgba(47, 111, 237, 0); }
  25% { box-shadow: 0 0 0 3px rgba(47, 111, 237, .35); }
}

.card .thumb {
  width: 150px; min-width: 150px;
  background: #eef1f5 center / cover no-repeat;
  border-right: 1px solid var(--line);
}
.card .body { padding: 14px 16px; flex: 1; min-width: 0; }

.title-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.favicon { width: 16px; height: 16px; border-radius: 3px; flex: none; }
.card .title { font-size: 16px; font-weight: 600; margin: 0; line-height: 1.3; overflow-wrap: anywhere; }
.card .title a { color: inherit; text-decoration: none; }
.card .title a:hover { text-decoration: underline; }

.desc {
  margin: 6px 0 0; color: var(--muted); font-size: 13.5px; line-height: 1.45;
  display: -webkit-box; -webkit-line-clamp: 3; line-clamp: 3;
  -webkit-box-orient: vertical; overflow: hidden;
}
.host { margin: 10px 0 0; color: var(--muted); font-size: 12px; }
.edited-flag { color: var(--muted); font-size: 11px; font-style: italic; }

.badge { font-size: 11px; font-weight: 600; border-radius: 999px; padding: 2px 9px; flex: none; }
.badge.readlater { background: #fff3e0; color: #b0621a; border: 1px solid #f6ddb8; }
.badge.archived { background: #eef0f2; color: #667080; border: 1px solid #dfe3e8; }

.tags { margin-top: 10px; display: flex; flex-wrap: wrap; gap: 6px; }
.chip {
  background: #eef3ff; color: #2554b0; border: 1px solid #d7e2fb;
  border-radius: 999px; padding: 3px 10px; font-size: 12px;
  display: inline-flex; align-items: center; gap: 6px;
}
.chip .x { cursor: pointer; font-weight: 700; color: #6f8bc7; }
.chip.suggest { background: #f3f4f6; color: #444; border-color: var(--line); cursor: pointer; }
.chip.suggest.on { background: #eef3ff; color: #2554b0; border-color: #d7e2fb; }

.note {
  margin-top: 10px; background: #fffdf3; border: 1px solid #efe6c4;
  border-radius: 8px; padding: 9px 11px; font-size: 13px; color: #5f5636;
}
.note div { margin: 2px 0; }
.note ul { margin: 4px 0; padding-left: 20px; }
.note li { margin: 2px 0; }
.note code { background: #efe9d0; border-radius: 4px; padding: 1px 4px; font-size: 12px; }
.note a { color: var(--accent); }

.fetchwarn {
  margin: 6px 0 0; color: var(--warn-ink); font-size: 12.5px;
  background: var(--warn-bg); border: 1px solid var(--warn-line);
  border-radius: 7px; padding: 7px 9px;
}

.actions { margin-top: 12px; display: flex; flex-wrap: wrap; gap: 12px; }
.linkbtn {
  background: none; border: none; padding: 0; cursor: pointer;
  color: var(--accent); font-size: 12.5px; font-weight: 600;
}
.linkbtn.muted { color: var(--muted); }

/* Inline editors */
.editor { width: 100%; }
.editor label {
  display: block; font-size: 11px; color: var(--muted); margin: 10px 0 4px;
  text-transform: uppercase; letter-spacing: .03em;
}
.editor label:first-child { margin-top: 0; }
.editor input[type="text"], .editor textarea {
  width: 100%; border: 1px solid var(--line); border-radius: 7px;
  padding: 8px 9px; font-size: 14px; font-family: inherit; outline: none;
}
.editor input[type="text"]:focus, .editor textarea:focus { border-color: var(--accent); }
.editor textarea { resize: vertical; min-height: 54px; }
.editor .checkline { text-transform: none; letter-spacing: 0; font-size: 13px; color: var(--ink); display: flex; align-items: center; gap: 6px; }
.editor .checkline input { width: auto; }
.chip-input { display: flex; flex-wrap: wrap; gap: 6px; border: 1px solid var(--line); border-radius: 7px; padding: 6px; }
.chip-input input { border: none; outline: none; flex: 1; min-width: 120px; font-size: 14px; padding: 3px; }
.editor .row { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
.editor .row button { border-radius: 7px; padding: 7px 14px; font-size: 13px; font-weight: 600; cursor: pointer; border: 1px solid var(--line); }
.editor .save { background: var(--accent); color: #fff; border-color: var(--accent); }
.editor .cancel { background: #fff; color: var(--ink); }

/* Loading skeleton */
.card.pending .body { display: flex; flex-direction: column; justify-content: center; }
.skeleton { background: #eef1f5; border-radius: 6px; height: 12px; }
.skeleton.t { height: 16px; width: 55%; margin-bottom: 10px; }
.skeleton.d { width: 90%; margin-bottom: 6px; }
.skeleton.d2 { width: 70%; }
.fetching { color: var(--muted); font-size: 12px; }
.spin {
  display: inline-block; width: 13px; height: 13px; border: 2px solid var(--line);
  border-top-color: var(--accent); border-radius: 50%; animation: sp .7s linear infinite;
  vertical-align: -2px; margin-right: 6px;
}
@keyframes sp { to { transform: rotate(360deg); } }

/* Empty states */
.empty {
  text-align: center; color: var(--muted); padding: 60px 20px;
  border: 1px dashed var(--line); border-radius: 12px; margin-top: 16px;
}
.empty[hidden] { display: none; }
.empty strong { color: var(--ink); }

input.content:
// Bookmarks app — UI and interaction wiring.
// Behaviour is derived from the approved scenarios SCN-001..SCN-012.
// Pure logic lives in the imported modules; this file handles state + DOM.

import { loadBookmarks, saveBookmarks } from "./store.mjs";
import {
  normalizeUrl,
  isValidLink,
  findDuplicate,
  hostFromUrl,
  makeId,
} from "./model.mjs";
import { buildMatcher, toRecord } from "./search.mjs";
import { renderMarkdown, escapeHtml } from "./markdown.mjs";

// ---- State ----------------------------------------------------------------
let bookmarks = loadBookmarks();
let view = "all"; // all | readlater | archive
let query = "";
let filterTags = [];
let flashId = null;
let editingId = null; // bookmark being edited (link/title/description)
let organizeId = null; // bookmark whose tags & note are being edited
let organizeDraft = null; // { tags: string[], note: string }

// ---- DOM refs -------------------------------------------------------------
const els = {
  saver: document.getElementById("saver"),
  urlInput: document.getElementById("urlInput"),
  saveBtn: document.getElementById("saveBtn"),
  notice: document.getElementById("notice"),
  viewbar: document.getElementById("viewbar"),
  searchInput: document.getElementById("searchInput"),
  filterbar: document.getElementById("filterbar"),
  resultmeta: document.getElementById("resultmeta"),
  list: document.getElementById("list"),
  empty: document.getElementById("empty"),
};

// ---- Persistence ----------------------------------------------------------
function persist() {
  // Never persist the transient "pending" flag.
  saveBookmarks(bookmarks.map(({ pending, ...rest }) => rest));
}

// ---- Metadata fetch (SCN-001, SCN-008) ------------------------------------
async function fetchMetadata(url) {
  try {
    const res = await fetch(`/api/metadata?url=${encodeURIComponent(url)}`);
    if (!res.ok) return { error: true, host: hostFromUrl(url) };
    return await res.json();
  } catch {
    return { error: true, host: hostFromUrl(url) };
  }
}

async function resolveDetails(entry) {
  entry.pending = true;
  entry.error = false;
  render();
  const meta = await fetchMetadata(entry.url);
  if (meta.error) {
    entry.error = true;
    entry.host = meta.host || hostFromUrl(entry.url);
    if (!entry.title) entry.title = entry.url;
    entry.description = entry.description || "";
    entry.favicon = entry.favicon || faviconGuess(entry.url);
    entry.image = entry.image || "";
  } else {
    entry.error = false;
    entry.title = meta.title || entry.title || entry.url;
    entry.description = meta.description || "";
    entry.host = meta.host || hostFromUrl(entry.url);
    entry.favicon = meta.favicon || faviconGuess(entry.url);
    entry.image = meta.image || "";
  }
  entry.pending = false;
}

function faviconGuess(url) {
  try {
    return new URL("/favicon.ico", url).href;
  } catch {
    return "";
  }
}

// ---- Save flow (SCN-001, SCN-008, SCN-009, SCN-011) -----------------------
els.saver.addEventListener("submit", async (e) => {
  e.preventDefault();
  const raw = els.urlInput.value.trim();
  if (!raw) return; // empty input: do nothing
  const url = normalizeUrl(raw);
  if (!isValidLink(url)) {
    showNotice("That doesn't look like a valid link — please check it and try again.", null, true);
    return;
  }
  const dup = findDuplicate(bookmarks, url);
  if (dup) {
    els.urlInput.value = "";
    const where = dup.archived ? " It's in your Archive." : "";
    showNotice("You've already saved this link." + where, dup);
    return;
  }
  const entry = {
    id: makeId(),
    url,
    title: "",
    description: "",
    host: hostFromUrl(url),
    favicon: "",
    image: "",
    tags: [],
    note: "",
    readLater: false,
    archived: false,
    edited: false,
    error: false,
    createdAt: Date.now(),
    pending: true,
  };
  bookmarks.unshift(entry);
  els.urlInput.value = "";
  els.saveBtn.disabled = true;
  render();
  await resolveDetails(entry);
  persist();
  els.saveBtn.disabled = false;
  render();
});

// ---- View tabs (SCN-006, SCN-007) -----------------------------------------
els.viewbar.addEventListener("click", (e) => {
  const tab = e.target.closest(".viewtab");
  if (!tab) return;
  view = tab.dataset.view;
  closeEditors();
  render();
});

// ---- Search (SCN-005) -----------------------------------------------------
els.searchInput.addEventListener("input", (e) => {
  query = e.target.value;
  render();
});

// ---- Filter bar (SCN-004) -------------------------------------------------
els.filterbar.addEventListener("click", (e) => {
  const chip = e.target.closest("[data-filter-tag]");
  if (chip) {
    const t = chip.dataset.filterTag;
    const i = filterTags.indexOf(t);
    if (i >= 0) filterTags.splice(i, 1);
    else filterTags.push(t);
    render();
    return;
  }
  if (e.target.closest("[data-action='clear-filters']")) {
    filterTags = [];
    query = "";
    els.searchInput.value = "";
    render();
  }
});

// ---- Notice banner --------------------------------------------------------
let noticeTimer = null;
function showNotice(text, target, isWarn = false) {
  els.notice.innerHTML = "";
  els.notice.classList.toggle("warn", !!isWarn);
  const span = document.createElement("span");
  span.textContent = text;
  els.notice.appendChild(span);
  if (target) {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.textContent = "Show it";
    btn.addEventListener("click", () => revealBookmark(target));
    els.notice.appendChild(btn);
  }
  els.notice.hidden = false;
  clearTimeout(noticeTimer);
  noticeTimer = setTimeout(() => { els.notice.hidden = true; }, 6000);
}

function revealBookmark(target) {
  if (target.archived) view = "archive";
  else if (view === "readlater" && !target.readLater) view = "all";
  query = "";
  filterTags = [];
  els.searchInput.value = "";
  flashId = target.id;
  render();
  const el = els.list.querySelector(`[data-id="${target.id}"]`);
  if (el) el.scrollIntoView({ behavior: "smooth", block: "center" });
  setTimeout(() => { flashId = null; }, 1600);
}

// ---- Card action delegation ----------------------------------------------
els.list.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-action]");
  if (!btn) return;
  const card = e.target.closest("[data-id]");
  const b = card && bookmarks.find((x) => x.id === card.dataset.id);
  const action = btn.dataset.action;

  switch (action) {
    case "edit":
      if (b) { closeEditors(); editingId = b.id; render(); }
      break;
    case "organize":
      if (b) {
        closeEditors();
        organizeId = b.id;
        organizeDraft = { tags: [...(b.tags || [])], note: b.note || "" };
        render();
      }
      break;
    case "readlater":
      if (b) { b.readLater = !b.readLater; persist(); render(); }
      break;
    case "archive":
      if (b) { b.archived = true; closeEditors(); persist(); render(); }
      break;
    case "restore":
      if (b) { b.archived = false; persist(); render(); }
      break;
    case "retry":
      if (b) { resolveDetails(b).then(() => { persist(); render(); }); }
      break;
    case "save-edit":
      if (b) saveEdit(b, card);
      break;
    case "cancel-edit":
      closeEditors(); render();
      break;
    case "org-toggle":
      toggleDraftTag(btn.dataset.tag, card);
      break;
    case "org-remove":
      removeDraftTag(btn.dataset.tag, card);
      break;
    case "save-org":
      if (b) saveOrganize(b, card);
      break;
    case "cancel-org":
      closeEditors(); render();
      break;
  }
});

function closeEditors() {
  editingId = null;
  organizeId = null;
  organizeDraft = null;
}

// ---- Edit save (SCN-002) --------------------------------------------------
async function saveEdit(b, card) {
  const urlVal = normalizeUrl(card.querySelector(".edit-url").value);
  const refetch = card.querySelector(".edit-refetch").checked;
  const titleVal = card.querySelector(".edit-title").value.trim();
  const descVal = card.querySelector(".edit-desc").value.trim();
  const newUrl = isValidLink(urlVal) ? urlVal : b.url;

  b.url = newUrl;
  if (refetch) {
    editingId = null;
    await resolveDetails(b);
    b.edited = true;
    persist();
    render();
    return;
  }
  b.title = titleVal || b.title;
  b.description = descVal;
  b.host = hostFromUrl(newUrl);
  b.favicon = faviconGuess(newUrl);
  b.edited = true;
  editingId = null;
  persist();
  render();
}

// ---- Organize save (SCN-003) ----------------------------------------------
function syncDraftNote(card) {
  const noteEl = card && card.querySelector(".org-note");
  if (noteEl && organizeDraft) organizeDraft.note = noteEl.value;
}

function toggleDraftTag(tag, card) {
  if (!organizeDraft || !tag) return;
  syncDraftNote(card);
  const i = organizeDraft.tags.indexOf(tag);
  if (i >= 0) organizeDraft.tags.splice(i, 1);
  else organizeDraft.tags.push(tag);
  render();
}

function removeDraftTag(tag, card) {
  if (!organizeDraft || !tag) return;
  syncDraftNote(card);
  const i = organizeDraft.tags.indexOf(tag);
  if (i >= 0) organizeDraft.tags.splice(i, 1);
  render();
}

function addDraftTag(value, card) {
  const t = value.trim().replace(/,+$/, "").trim();
  if (!t || !organizeDraft) return;
  syncDraftNote(card);
  if (!organizeDraft.tags.includes(t)) organizeDraft.tags.push(t);
  render();
}

function saveOrganize(b, card) {
  const newEl = card.querySelector(".org-newtag");
  if (newEl && newEl.value.trim()) {
    const t = newEl.value.trim().replace(/,+$/, "").trim();
    if (t && !organizeDraft.tags.includes(t)) organizeDraft.tags.push(t);
  }
  syncDraftNote(card);
  b.tags = [...organizeDraft.tags];
  b.note = (organizeDraft.note || "").trim();
  closeEditors();
  persist();
  render();
}

// ---- Derived data ---------------------------------------------------------
function allTags() {
  const set = [];
  for (const b of bookmarks) {
    for (const t of b.tags || []) if (!set.includes(t)) set.push(t);
  }
  return set.sort((a, b) => a.localeCompare(b));
}

function inView(b) {
  if (view === "archive") return !!b.archived;
  if (b.archived) return false;
  if (view === "readlater") return !!b.readLater;
  return true;
}

function makeMatcher() {
  return query.trim() ? buildMatcher(query) : null;
}

function visibleBookmarks(matcher) {
  return bookmarks.filter((b) => {
    if (!inView(b)) return false;
    if (filterTags.length && !filterTags.every((t) => (b.tags || []).includes(t))) return false;
    if (matcher && !b.pending) return matcher(toRecord(b));
    return true;
  });
}

// ---- Render ---------------------------------------------------------------
function render() {
  const matcher = makeMatcher();
  renderTabs();
  renderFilterBar();
  const visible = visibleBookmarks(matcher);
  renderResultMeta(visible);
  renderList(visible);
  renderEmpty(visible);
  postRender();
}

function renderTabs() {
  const readCount = bookmarks.filter((b) => b.readLater && !b.archived).length;
  const archiveCount = bookmarks.filter((b) => b.archived).length;
  for (const tab of els.viewbar.querySelectorAll(".viewtab")) {
    const v = tab.dataset.view;
    const on = v === view;
    tab.classList.toggle("on", on);
    tab.setAttribute("aria-pressed", String(on));
    let label = v === "all" ? "All" : v === "readlater" ? "Read Later" : "Archive";
    if (v === "readlater") label += ` <span class="count">${readCount}</span>`;
    if (v === "archive") label += ` <span class="count">${archiveCount}</span>`;
    tab.innerHTML = label;
  }
}

function renderFilterBar() {
  const tags = allTags();
  const parts = [];
  if (tags.length) {
    parts.push('<span class="flabel">Filter by tag:</span>');
    for (const t of tags) {
      const on = filterTags.includes(t) ? " on" : "";
      parts.push(`<span class="filter-chip${on}" data-filter-tag="${escapeHtml(t)}">${escapeHtml(t)}</span>`);
    }
    if (filterTags.length || query.trim()) {
      parts.push('<button class="clearf" type="button" data-action="clear-filters">Clear</button>');
